import { useEffect, useMemo, useState } from 'react';
import { selectSelectedBlock, selectSelectedProject, setSelectedBlockReducer, setSelectedProjectReducer, useActiveProjectQuery, useAppDispatch, useAppSelector, useBlocksForProjectQuery, } from '@igblsln/store';
export const usePortionFilters = () => {
    const dispatch = useAppDispatch();
    const selectedProjectKey = useAppSelector(selectSelectedProject);
    const selectedBlockKey = useAppSelector(selectSelectedBlock);
    const [selectedTypeKey, setSelectedTypeKey] = useState('all');
    const [searchText, setSearchText] = useState('');
    const { data: projects } = useActiveProjectQuery();
    const { data: blockData } = useBlocksForProjectQuery({ projectId: selectedProjectKey }, { skip: !selectedProjectKey });
    useEffect(() => {
        if (projects && projects.length > 0 && selectedProjectKey === null) {
            dispatch(setSelectedProjectReducer(projects[0].key));
        }
    }, [dispatch, projects, selectedProjectKey]);
    useEffect(() => {
        if (blockData && blockData.length > 0 && selectedBlockKey === null) {
            dispatch(setSelectedBlockReducer(blockData[0].key));
        }
    }, [blockData, dispatch, selectedBlockKey]);
    const handlers = useMemo(() => ({
        setSelectedProjectKey: (value) => {
            dispatch(setSelectedProjectReducer(value));
            dispatch(setSelectedBlockReducer(null));
        },
        setSelectedBlockKey: (value) => {
            dispatch(setSelectedBlockReducer(value));
        },
        setSelectedTypeKey,
        setSearchText,
    }), [dispatch]);
    return Object.assign({ projects: projects || [], blocks: blockData || [], selectedProjectKey,
        selectedBlockKey,
        selectedTypeKey,
        searchText }, handlers);
};
