const findSegmentNames = (segments, typeNames) => {
    const normalizedTypeNames = typeNames.map((typeName) => normalizeName(typeName));
    const matches = segments.filter((segment) => {
        const segmentTypeName = normalizeName(segment.segment_type_name);
        return normalizedTypeNames.some((typeName) => segmentTypeName === typeName || segmentTypeName.includes(typeName));
    });
    return matches
        .reduce((details, segment) => [...details, ...(segment.segment_details || [])], [])
        .map((detail) => detail.segment_name)
        .filter(Boolean);
};
const getSegmentNamesByType = (segments, sectionType) => {
    return findSegmentNames(segments, SECTION_TYPE_ALIASES[sectionType] || [sectionType]);
};
const uniqueNames = (names) => names.filter((name, index, values) => !!name && values.indexOf(name) === index);
const resolveTemplateNames = (template, segments, subSections, blockName) => {
    switch (template.source) {
        case 'block':
            return [blockName];
        case 'block_sides':
            return getSegmentNamesByType(segments, 'Block Sides');
        case 'column_foundation_batches':
            return getSegmentNamesByType(segments, 'Column Foundation Batch');
        case 'floors':
            return getSegmentNamesByType(segments, 'Floor');
        case 'lifts':
            return getSegmentNamesByType(segments, 'Lift');
        case 'sumps':
            return getSegmentNamesByType(segments, 'Sump');
        case 'ohts':
            return getSegmentNamesByType(segments, 'OHT');
        case 'apartments':
            return getSegmentNamesByType(segments, 'Apartment');
        case 'staircases':
            return getSegmentNamesByType(segments, 'Staircase');
        case 'staircase_wells':
            return uniqueNames(subSections.filter((row) => row.section_type === 'Staircase' && row.sub_section_type === 'Stairs Well').map((row) => row.section_name));
        case 'staircase_headrooms':
            return uniqueNames(subSections.filter((row) => row.section_type === 'Staircase' && row.sub_section_type === 'Head Room').map((row) => row.section_name));
        case 'lift_rooms':
            return uniqueNames(subSections.filter((row) => row.section_type === 'Lift' && row.sub_section_type === 'Lift Room').map((row) => row.section_name));
        default:
            return [];
    }
};
export const buildProcedureRows = (templateNames, segments, subSections, blockName) => {
    const shouldGenerateProcedure = (procedureName) => templateNames.length === 0 || templateNames.includes(procedureName);
    const templates = templateNames.length > 0
        ? PROCEDURE_TEMPLATES.filter((template) => templateNames.includes(template.procedure_name))
        : PROCEDURE_TEMPLATES;
    const rows = [];
    templates.forEach((template) => {
        const names = resolveTemplateNames(template, segments, subSections, blockName);
        names.forEach((name) => {
            rows.push({
                procedure_name: template.procedure_name,
                section_type: template.section_type,
                section_name: name,
                sub_section_type: template.sub_section_type,
                sub_section_name: template.sub_section_name_builder(name, blockName),
                process_name: template.process_name_builder(name),
                milestones: template.milestones,
            });
        });
    });
    const floorNames = getSegmentNamesByType(segments, 'Floor');
    const staircaseNames = getSegmentNamesByType(segments, 'Staircase');
    const liftNames = getSegmentNamesByType(segments, 'Lift');
    if (shouldGenerateProcedure('Roof Slab')) {
        floorNames.forEach((floorName) => {
            rows.push({
                procedure_name: 'Roof Slab',
                section_type: 'Floor',
                section_name: floorName,
                sub_section_type: 'Floor',
                sub_section_name: floorName,
                process_name: `${floorName}_Roof Slab Process`,
                milestones: ['Centring', 'Concrete'],
            });
        });
    }
    if (shouldGenerateProcedure('Staircase Slab')) {
        staircaseNames.forEach((staircaseName) => {
            floorNames.forEach((floorName) => {
                rows.push({
                    procedure_name: 'Staircase Slab',
                    section_type: 'Staircase',
                    section_name: staircaseName,
                    sub_section_type: floorName,
                    sub_section_name: `${staircaseName}.${floorName}`,
                    process_name: `${staircaseName}_${floorName}_Slab Process`,
                    milestones: ['Slab Work'],
                });
            });
        });
    }
    if (shouldGenerateProcedure('Column Extension')) {
        liftNames.forEach((liftName) => {
            rows.push({
                procedure_name: 'Column Extension',
                section_type: 'Lift',
                section_name: liftName,
                sub_section_type: 'Lift Room',
                sub_section_name: `${liftName}.Lift Room`,
                process_name: `${liftName}_Lift Room_Column Extension Process`,
                milestones: ['Column Extension Work'],
            });
        });
        staircaseNames.forEach((staircaseName) => {
            rows.push({
                procedure_name: 'Column Extension',
                section_type: 'Staircase',
                section_name: staircaseName,
                sub_section_type: 'Head Room',
                sub_section_name: `${staircaseName}.Head Room`,
                process_name: `${staircaseName}_Head Room_Column Extension Process`,
                milestones: ['Column Extension Work'],
            });
        });
    }
    return rows;
};
